/* Host tests for the firmware.
 *
 * The CRC is the part that must be exactly right: tools/mkimagetable.py bakes
 * a zlib.crc32 value into the image table, and if the firmware computes
 * anything different it will reject every image at boot and the socket will
 * stay dead. The expected values here are generated by the Python side, so
 * this test compares two independent implementations rather than a function
 * against itself.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "fastprom_crc32.h"
#include "fastprom_fabric.h"
#include "fastprom_loader.h"
#include "vectors.h"

static fastprom_fabric_t mock_fabric;
fastprom_fabric_t *fastprom_fabric_mock = &mock_fabric;

static int failures;

static void expect_u32(const char *what, uint32_t got, uint32_t want)
{
    if (got != want) {
        printf("FAIL %s: got 0x%08x want 0x%08x\n", what, got, want);
        failures++;
    }
}

static void expect_status(const char *what, int got, int want)
{
    if (got != want) {
        printf("FAIL %s: got status %d want %d\n", what, got, want);
        failures++;
    }
}

int main(void)
{
    /* ---- CRC against the Python implementation ------------------------ */
    for (int i = 0; i < N_CRC_VECTORS; i++) {
        const crc_vector_t *v = &crc_vectors[i];
        expect_u32(v->name, fastprom_crc32(v->data, v->len), v->expect);
    }
    printf("crc32: checked %d vectors against zlib.crc32\n", N_CRC_VECTORS);

    /* ---- loader error paths ------------------------------------------- */
    static uint8_t img_data[256];
    for (int i = 0; i < 256; i++)
        img_data[i] = (uint8_t)(i * 7 + 3);

    fastprom_image_t img = {
        .name = "test", .crc32 = fastprom_crc32(img_data, 256),
        .data = img_data,
    };
    fastprom_image_table_t table = {
        .magic = FASTPROM_IMAGE_MAGIC, .version = FASTPROM_IMAGE_VERSION,
        .part = "512x8", .depth = 256, .width = 8,
        .image_count = 1, .images = &img,
    };

    /* An unconfigured fabric reads as zero. The loader must refuse rather
     * than write into nothing and then declare the outputs live. */
    memset(&mock_fabric, 0, sizeof mock_fabric);
    expect_status("unconfigured fabric",
                  fastprom_load(&table, 0), FASTPROM_ERR_NO_FABRIC);
    expect_u32("ctrl left clear after no-fabric", mock_fabric.ctrl, 0);

    mock_fabric.id = FASTPROM_FABRIC_MAGIC;

    table.magic = 0xDEADBEEF;
    expect_status("bad table magic",
                  fastprom_load(&table, 0), FASTPROM_ERR_BAD_TABLE);
    table.magic = FASTPROM_IMAGE_MAGIC;

    table.version = 99;
    expect_status("future format version",
                  fastprom_load(&table, 0), FASTPROM_ERR_BAD_VERSION);
    table.version = FASTPROM_IMAGE_VERSION;

    expect_status("bank out of range",
                  fastprom_load(&table, 5), FASTPROM_ERR_BAD_BANK);

    img.crc32 ^= 0xFFFFFFFFu;
    expect_status("corrupt image",
                  fastprom_load(&table, 0), FASTPROM_ERR_BAD_CRC);
    expect_u32("ctrl left clear after bad crc", mock_fabric.ctrl, 0);
    img.crc32 ^= 0xFFFFFFFFu;

    /* ---- success path ------------------------------------------------- */
    expect_status("good image", fastprom_load(&table, 0), FASTPROM_OK);
    expect_u32("ready set after a verified load",
               mock_fabric.ctrl, FASTPROM_CTRL_READY);
    expect_u32("last word reached the data register",
               mock_fabric.data, img_data[255]);

    if (failures == 0) {
        printf("test_fw: PASS\n");
        return 0;
    }
    printf("test_fw: FAIL (%d)\n", failures);
    return 1;
}
